 const reviewBadges=blockReviewBadgesHtml(block);
 const head=`<div class="block-head"><div class="block-title-wrap"><div class="block-title">${esc(block.title||'Пункт')}${block.required?'<span class="req">*</span>':''}</div>${reviewBadges}</div>${theory}</div>`;
