function referenceUploadErrorMessage(e){const code=String(e?.code||e?.message||'');if(code.includes('SOURCE_TOO_LARGE'))return'Картинка більша за 25 МБ. Оберіть менший файл.';if(code.includes('UNSUPPORTED_IMAGE')||code.includes('IMAGE_DECODE_FAILED'))return'Цей формат картинки браузер не може обробити. Використайте JPG, PNG або WEBP.';if(code.includes('storage/unauthorized'))return'Firebase Storage відхилив завантаження (storage/unauthorized). Треба один раз опублікувати правила Storage для Режисерської лабораторії.';if(code.includes('storage/bucket-not-found')||code.includes('storage/project-not-found'))return'Firebase Storage для цього проєкту не активований або вказаний неправильний bucket.';if(code.includes('storage/quota-exceeded'))return'Перевищено ліміт Firebase Storage.';if(code.includes('storage/retry-limit-exceeded'))return'Firebase Storage не відповів вчасно. Перевірте мережу або правила Storage.';if(code.includes('UPLOAD_TIMEOUT'))return'Firebase Storage не почав завантаження за 20 секунд. Найчастіше це означає, що правила Storage ще не опубліковані.';if(code.includes('storage/canceled'))return'Завантаження було перервано.';return`Не вдалося завантажити референс${code?` (${code})`:''}.`}
async function uploadTableImages(blockId,rowIndex,colIndex,fileList){const files=[...(fileList||[])].filter(f=>f&&String(f.type||'').startsWith('image/'));if(!files.length){alert('Не знайдено файлів зображень. Оберіть JPG, PNG або WEBP.');return;}const section=schema.sections.find(s=>(s.blocks||[]).some(b=>b.id===blockId)),block=section?.blocks?.find(b=>b.id===blockId);if(!section||!block)return;const t=appEl.querySelector(`[data-table="${CSS.escape(blockId)}"]`),note=t?.closest('.work-block')?.querySelector(`[data-block-save-note="${CSS.escape(blockId)}"]`);try{if(note)note.textContent='Перевіряємо збереження…';const probeAt=new Date().toISOString();await updateDoc(workRef,{updatedAt:probeAt,studentUpdatedAt:probeAt});const answer=collectSection(section.id)?.[blockId]||{rows:[]},types=tableColumnTypes(block);while(answer.rows.length<=rowIndex)answer.rows.push((block.columns||[]).map((_,i)=>types[i]==='images'?[]:types[i]==='duration'?0:''));const current=tableImages(answer.rows[rowIndex]?.[colIndex]),added=[];for(let i=0;i<files.length;i++){const original=files[i];if(note)note.textContent=`Готуємо референс ${i+1}/${files.length}…`;const prepared=await prepareReferenceImage(original),file=prepared.file;const safe=file.name.replace(/[^a-zA-Z0-9а-яА-ЯіїєґІЇЄҐ._-]+/g,'_'),path=`directing-lab/${key}/${blockId}/references/${Date.now()}-${Math.random().toString(36).slice(2,7)}-${safe}`;const url=await uploadReferenceWithProgress(path,file,pct=>{if(note)note.textContent=`Завантаження ${i+1}/${files.length} · ${pct}%`});added.push({name:original.name,url,size:file.size,originalSize:original.size,type:file.type,compressed:prepared.compressed,uploadedAt:new Date().toISOString()})}answer.rows[rowIndex][colIndex]=[...current,...added];answer.columns=[...(block.columns||[])];answer.columnTypes=[...types];answer.tableSchemaVersion=Number(block.tableSchemaVersion||1);const now=new Date().toISOString();if(note)note.textContent='Зберігаємо референси…';await updateDoc(workRef,{[`answers.${blockId}`]:answerToFirestore(block,answer),updatedAt:now,studentUpdatedAt:now});work.answers={...(work.answers||{}),[blockId]:answer};dirtyBlocks.delete(String(blockId));if(note)note.textContent=`Додано ${added.length} референс${added.length===1?'':'и'} ✓`;const drafts=captureDirtyAnswers();work=mergeDirtyAnswers(work,drafts);render()}catch(e){console.error('Reference upload failed',e);if(note)note.textContent='Не вдалося завантажити референси';const retry=appEl.querySelector(`[data-table-image-upload="${CSS.escape(String(blockId))}"][data-row="${rowIndex}"][data-col="${colIndex}"]`)?.closest('.table-image-add')?.querySelector('span');if(retry)retry.textContent='＋ Додати референс';const code=String(e?.code||'');alert(code.includes('firestore/')||code.includes('permission-denied')?firestoreWriteErrorMessage(e):referenceUploadErrorMessage(e))}}
async function removeTableImage(blockId,rowIndex,colIndex,imageIndex){const section=schema.sections.find(s=>(s.blocks||[]).some(b=>b.id===blockId)),block=section?.blocks?.find(b=>b.id===blockId);if(!section||!block)return;const answer=collectSection(section.id)?.[blockId];if(!answer?.rows?.[rowIndex])return;const imgs=tableImages(answer.rows[rowIndex][colIndex]);imgs.splice(imageIndex,1);answer.rows[rowIndex][colIndex]=imgs;answer.columns=[...(block.columns||[])];answer.columnTypes=[...tableColumnTypes(block)];answer.tableSchemaVersion=Number(block.tableSchemaVersion||1);const now=new Date().toISOString();await updateDoc(workRef,{[`answers.${blockId}`]:answerToFirestore(block,answer),updatedAt:now,studentUpdatedAt:now});work.answers={...(work.answers||{}),[blockId]:answer};const drafts=captureDirtyAnswers();work=mergeDirtyAnswers(work,drafts);render()}

function xmlEsc(s){return String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&apos;"}[c]))}
function safeFileName(s){return String(s||'student').replace(/[\\/:*?"<>|]+/g,'_').replace(/\s+/g,'_').slice(0,90)}
function docxRun(text,{bold=false,size=28}={}){return `<w:r><w:rPr><w:rFonts w:ascii="Times New Roman" w:hAnsi="Times New Roman" w:eastAsia="Times New Roman"/><w:sz w:val="${size}"/><w:szCs w:val="${size}"/>${bold?'<w:b/><w:bCs/>':''}<w:color w:val="000000"/></w:rPr><w:t xml:space="preserve">${xmlEsc(text)}</w:t></w:r>`}
function docxPara(text,{style='',bold=false,center=false,pageBreakBefore=false,firstLine=true,spaceBefore=0,spaceAfter=0}={}){
 const ppr=[style?`<w:pStyle w:val="${style}"/>`:'',center?'<w:jc w:val="center"/>':'<w:jc w:val="both"/>',firstLine?'<w:ind w:firstLine="709"/>':'',`<w:spacing w:before="${spaceBefore}" w:after="${spaceAfter}" w:line="360" w:lineRule="auto"/>`,pageBreakBefore?'<w:pageBreakBefore/>':''].join('');
 return `<w:p><w:pPr>${ppr}</w:pPr>${docxRun(text,{bold})}</w:p>`
}
