async function wordCompatibleImage(blob,img){let type=String(blob?.type||img?.type||'').toLowerCase();if(type.includes('jpeg')||type.includes('jpg'))return{blob,type:'image/jpeg',ext:'jpg'};if(type.includes('png'))return{blob,type:'image/png',ext:'png'};try{const decoded=await decodeReferenceImage(blob);try{const canvas=document.createElement('canvas');canvas.width=Math.max(1,decoded.width);canvas.height=Math.max(1,decoded.height);const c=canvas.getContext('2d',{alpha:false});c.fillStyle='#fff';c.fillRect(0,0,canvas.width,canvas.height);c.drawImage(decoded.source,0,0,canvas.width,canvas.height);const out=await new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(new Error('DOCX_IMAGE_CONVERT_FAILED')),'image/jpeg',.9));return{blob:out,type:'image/jpeg',ext:'jpg'}}finally{decoded.close?.()}}catch(e){throw new Error('DOCX_IMAGE_UNSUPPORTED: '+(e?.message||e))}}
function standaloneReferenceLinkPara(ctx,url){const clean=String(url||'').trim();if(!clean)return'';const rid=`rId${ctx.nextId++}`;ctx.rels.push({rid,url:clean});return `<w:p><w:pPr><w:jc w:val="center"/><w:spacing w:before="0" w:after="40"/></w:pPr><w:hyperlink r:id="${rid}" w:history="1"><w:r><w:rPr><w:rFonts w:ascii="Times New Roman" w:hAnsi="Times New Roman" w:eastAsia="Times New Roman"/><w:sz w:val="20"/><w:szCs w:val="20"/><w:color w:val="0563C1"/><w:u w:val="single"/></w:rPr><w:t>Відкрити референс</w:t></w:r></w:hyperlink></w:p>`}
async function standaloneImagePara(ctx,img,{maxW=300,maxH=210,center=false}={}){const url=String(img?.url||'').trim();if(!url)return'';try{const source=await wordReferenceBlob(img),compatible=await wordCompatibleImage(source,img),blob=compatible.blob,ext=compatible.ext,data=await blob.arrayBuffer();let w=720,h=480;try{const bmp=await createImageBitmap(blob);w=bmp.width||w;h=bmp.height||h;bmp.close?.()}catch{}const scale=Math.min(maxW/w,maxH/h,1),cx=Math.max(1,Math.round(w*scale*9525)),cy=Math.max(1,Math.round(h*scale*9525)),rid=`rId${ctx.nextId++}`,filename=`image${ctx.nextImage++}.${ext}`,docPr=1000+ctx.nextImage;ctx.images.push({rid,filename,data,ext});return `<w:p><w:pPr><w:jc w:val="${center?'center':'left'}"/><w:spacing w:before="0" w:after="50"/></w:pPr><w:r><w:drawing><wp:inline xmlns:wp="http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing" distT="0" distB="0" distL="0" distR="0"><wp:extent cx="${cx}" cy="${cy}"/><wp:docPr id="${docPr}" name="${xmlEsc(img?.name||'Reference')}"/><a:graphic xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main"><a:graphicData uri="http://schemas.openxmlformats.org/drawingml/2006/picture"><pic:pic xmlns:pic="http://schemas.openxmlformats.org/drawingml/2006/picture"><pic:nvPicPr><pic:cNvPr id="0" name="${xmlEsc(img?.name||filename)}"/><pic:cNvPicPr/></pic:nvPicPr><pic:blipFill><a:blip r:embed="${rid}"/><a:stretch><a:fillRect/></a:stretch></pic:blipFill><pic:spPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="${cx}" cy="${cy}"/></a:xfrm><a:prstGeom prst="rect"><a:avLst/></a:prstGeom></pic:spPr></pic:pic></a:graphicData></a:graphic></wp:inline></w:drawing></w:r></w:p>`}catch(e){console.warn('DOCX image embed failed - check Storage CORS',e);ctx.imageFailures=(ctx.imageFailures||0)+1;return standaloneReferenceLinkPara(ctx,url)}}
function docxTableRun(text,{bold=false,size=24}={}){return `<w:r><w:rPr><w:rFonts w:ascii="Times New Roman" w:hAnsi="Times New Roman" w:eastAsia="Times New Roman"/><w:sz w:val="${size}"/><w:szCs w:val="${size}"/>${bold?'<w:b/><w:bCs/>':''}</w:rPr><w:t xml:space="preserve">${xmlEsc(text)}</w:t></w:r>`}
function docxTableTextParas(value,{bold=false,center=false,size=24}={}){const lines=String(value??'').split(/\n+/).map(x=>x.trim()).filter(Boolean);if(!lines.length)return'<w:p><w:pPr><w:spacing w:before="0" w:after="0"/></w:pPr></w:p>';return lines.map(line=>`<w:p><w:pPr><w:jc w:val="${center?'center':'left'}"/><w:spacing w:before="0" w:after="30" w:line="276" w:lineRule="auto"/></w:pPr>${docxTableRun(line,{bold,size})}</w:p>`).join('')}
function docxTableWidths(cols,types){const weights=cols.map((c,i)=>{const t=types[i]||'text';if(t==='sequence')return .45;if(t==='duration')return 1.05;if(t==='images')return 1.85;const title=String(c||'');if(/опис|дії|зміст/i.test(title))return 1.65;if(/номер|сцена|одиниц/i.test(title))return 1.55;if(/епізод|блок/i.test(title))return 1.2;if(/хто|учас/i.test(title))return 1.15;return 1.25});const total=weights.reduce((a,b)=>a+b,0)||1,max=15400;let widths=weights.map(w=>Math.max(520,Math.round(max*w/total)));const diff=max-widths.reduce((a,b)=>a+b,0);widths[widths.length-1]+=diff;return widths}
function docxTableCell(content,width,{shade='',bold=false,center=false,gridSpan=1,size=24}={}){const p=content&&String(content).startsWith('<w:p')?content:docxTableTextParas(content,{bold,center,size});return `<w:tc><w:tcPr><w:tcW w:w="${Math.max(300,Math.round(width||1000))}" w:type="dxa"/>${gridSpan>1?`<w:gridSpan w:val="${gridSpan}"/>`:''}<w:vAlign w:val="top"/>${shade?`<w:shd w:val="clear" w:color="auto" w:fill="${shade}"/>`:''}<w:tcMar><w:top w:w="70" w:type="dxa"/><w:left w:w="70" w:type="dxa"/><w:bottom w:w="70" w:type="dxa"/><w:right w:w="70" w:type="dxa"/></w:tcMar></w:tcPr>${p}</w:tc>`}
async function standaloneTableToDocx(paras,ctx,block,answer){const rows=normalizeTableRows(block,answer),cols=block.columns||[],types=tableColumnTypes(block),dataRows=rows.filter(r=>r.some((v,i)=>tableCellHasValue(v,types[i])));if(!dataRows.length){paras.push(docxPara('Не заповнено',{firstLine:false,spaceAfter:80}));return}ctx.landscape=true;const widths=docxTableWidths(cols,types),grid=widths.map(w=>`<w:gridCol w:w="${w}"/>`).join('');const header=`<w:tr><w:trPr><w:tblHeader/></w:trPr>${cols.map((c,i)=>docxTableCell(String(c||''),widths[i],{shade:'E9EEF6',bold:true,center:types[i]==='sequence'||types[i]==='duration',size:22})).join('')}</w:tr>`;const body=[];for(let ri=0;ri<dataRows.length;ri++){const row=dataRows[ri],cells=[];for(let ci=0;ci<cols.length;ci++){const type=types[ci]||'text',v=row[ci];if(type==='sequence'){cells.push(docxTableCell(String(ri+1),widths[ci],{center:true,bold:true,size:24}));continue}if(type==='duration'){cells.push(docxTableCell(formatDuration(v),widths[ci],{center:true,size:24}));continue}if(type==='images'){const imgs=tableImages(v);let content='';for(const img of imgs){content+=await standaloneImagePara(ctx,img,{maxW:120,maxH:90,center:true})}if(!content)content=docxTableTextParas('',{center:true,size:24});cells.push(docxTableCell(content,widths[ci]));continue}cells.push(docxTableCell(String(v??''),widths[ci],{size:24}))}body.push(`<w:tr>${cells.join('')}</w:tr>`)}const durationIndex=types.findIndex(x=>x==='duration');if(durationIndex>=0){const before=Math.max(1,durationIndex),beforeWidth=widths.slice(0,durationIndex).reduce((a,b)=>a+b,0),after=cols.length-durationIndex-1;const footer=[];footer.push(docxTableCell('Загальний хронометраж',beforeWidth,{gridSpan:before,shade:'F5F7FA',bold:true,center:false,size:24}));footer.push(docxTableCell(formatDuration(tableDurationTotal(block,dataRows)),widths[durationIndex],{shade:'F5F7FA',bold:true,center:true,size:24}));for(let i=0;i<after;i++)footer.push(docxTableCell('',widths[durationIndex+1+i],{shade:'F5F7FA'}));body.push(`<w:tr>${footer.join('')}</w:tr>`)}paras.push(`<w:tbl><w:tblPr><w:tblW w:w="15400" w:type="dxa"/><w:tblLayout w:type="fixed"/><w:tblBorders><w:top w:val="single" w:sz="6" w:color="AEB8C6"/><w:left w:val="single" w:sz="6" w:color="AEB8C6"/><w:bottom w:val="single" w:sz="6" w:color="AEB8C6"/><w:right w:val="single" w:sz="6" w:color="AEB8C6"/><w:insideH w:val="single" w:sz="4" w:color="CFD6DF"/><w:insideV w:val="single" w:sz="4" w:color="CFD6DF"/></w:tblBorders></w:tblPr><w:tblGrid>${grid}</w:tblGrid>${header}${body.join('')}</w:tbl>`);paras.push('<w:p><w:pPr><w:spacing w:after="80"/></w:pPr></w:p>')}


