 appEl.querySelectorAll('[data-export-parameters]').forEach(b=>b.onclick=downloadProjectParametersWord);
 appEl.querySelectorAll('[data-export-ideological]').forEach(b=>b.onclick=downloadIdeologicalWord);
 appEl.querySelectorAll('[data-export-chapter2]').forEach(b=>b.onclick=downloadChapter2Word);
 appEl.querySelectorAll('[data-export-scenario-section]').forEach(b=>b.onclick=()=>downloadScenarioSectionWord(b.dataset.exportScenarioSection));
